static vector<string> vals(const Request&r,const string&k){vector<string> v;for(auto &h:r.headers)if(h.first==k)v.push_back(h.second);return v;}
static bool hasToken(const string&s,const string&t){for(auto &x:split(s,','))if(lower(trim(x))==t)return true;return false;}
static bool utf8(const string&s){for(size_t i=0;i<s.size();){unsigned char c=s[i++];if(c<128)continue;int n;uint32_t v;if(c>=0xc2&&c<=0xdf){n=1;v=c&31;}else if(c>=0xe0&&c<=0xef){n=2;v=c&15;}else if(c>=0xf0&&c<=0xf4){n=3;v=c&7;}else return false;if(i+n>s.size())return false;for(int j=0;j<n;j++){unsigned char d=s[i++];if((d&0xc0)!=0x80)return false;v=(v<<6)|(d&63);}if((n==2&&v<0x800)||(n==3&&v<0x10000)||v>0x10ffff||(v>=0xd800&&v<=0xdfff))return false;}return true;}
