static bool parseRange(const string&s,uint64_t size,uint64_t &start,uint64_t &len,bool &sat){sat=false;if(s.compare(0,6,"bytes=")!=0||s.find(',')!=string::npos)return false;string x=s.substr(6);auto p=x.find('-');if(p==string::npos||x.find('-',p+1)!=string::npos)return false;string a=x.substr(0,p),b=x.substr(p+1);uint64_t av=0,bv=0;if(a.empty()){if(!number(b,bv))return false;if(size&&bv){len=min(size,bv);start=size-len;sat=true;}return true;}if(!number(a,av)||(!b.empty()&&!number(b,bv)))return false;if(!b.empty()&&bv<av)return false;if(av>=size)return true;start=av;uint64_t end=b.empty()?size-1:min(size-1,bv);len=end-start+1;sat=true;return true;}
