static int chunks(const string&in,size_t pos,uint64_t limit,string &out,size_t &end){out.clear();size_t trailer=0;for(;;){auto p=in.find("\r\n",pos);if(p==string::npos)return in.size()-pos>8192?-1:0;string line=in.substr(pos,p-pos);auto semi=line.find(';');string h=line.substr(0,semi);if(h.empty())return -1;uint64_t n=0;for(char c:h){int x=hexval(c);if(x<0||n>(UINT64_MAX-x)/16)return -1;n=n*16+x;}if(semi!=string::npos)for(size_t i=semi+1;i<line.size();i++)if((unsigned char)line[i]<32||line[i]==127)return -1;pos=p+2;if(n>limit-out.size())return -2;if(n==0){for(;;){p=in.find("\r\n",pos);if(p==string::npos)return in.size()-pos>8192?-1:0;trailer+=p-pos+2;if(trailer>8192)return -1;if(p==pos){end=p+2;return 1;}string l=in.substr(pos,p-pos);auto c=l.find(':');if(c==string::npos||!token(l.substr(0,c))||l[0]==' '||l[0]=='\t'||l.find('\0')!=string::npos)return -1;pos=p+2;}}if(n>in.size()-pos)return 0;if(in.size()-pos-n<2)return 0;out.append(in,pos,n);pos+=n;if(in.compare(pos,2,"\r\n")!=0)return -1;pos+=2;}}
