static int waitfd(int fd,short ev,TP deadline){for(;;){auto ms=chrono::duration_cast<chrono::milliseconds>(deadline-Clock::now()).count();if(ms<=0)return 0;pollfd p{fd,ev,0};int n=poll(&p,1,(int)min<int64_t>(ms,INT32_MAX));if(n>0)return 1;if(n==0)return 0;if(errno!=EINTR)return -1;}}
