static string cachekey(const Request&r){return "http://"+r.host+r.target;}
static string acceptenc(const Request&r){string x;for(auto &v:vals(r,"accept-encoding")){if(!x.empty())x+=",";x+=v;}return x;}
static bool lookup(const Request&r,Response &z){if(!vals(r,"authorization").empty())return false;lock_guard<mutex>l(cmu);string k=cachekey(r);auto it=cachemap.find(k);if(it==cachemap.end())return false;if(it->second.expires<=Clock::now()){cacheused-=it->second.size;cachemap.erase(it);return false;}if(!it->second.vary.empty()&&it->second.vary!="="+acceptenc(r))return false;z=it->second.r;if(r.head)z.body.clear();return true;}
static void storecache(const Request&r,const Config&c,const UpResult&u){if(r.method!="GET"||u.response.status!=200||!vals(r,"authorization").empty()||u.response.body.size()>c.cache||!c.ttl)return;bool pub=false,forbid=false;uint64_t age=0;bool got=false,vary=false;for(auto&h:u.headers){if(h.first=="set-cookie")forbid=true;if(h.first=="vary")for(auto &t:split(h.second,',')){string v=lower(trim(t));if(v=="accept-encoding")vary=true;else forbid=true;}if(h.first=="cache-control")for(auto &t:split(h.second,',')){string v=lower(trim(t));if(v=="public")pub=true;else if(v=="private"||v.compare(0,8,"private=")==0||v=="no-store")forbid=true;else if(v.compare(0,8,"max-age=")==0){uint64_t n;if(number(v.substr(8),n)){age=n;got=true;}}}}if(!pub||forbid||!got||!age)return;uint64_t ms=age>UINT64_MAX/1000?c.ttl:min(c.ttl,age*1000);if(!ms)return;lock_guard<mutex>l(cmu);string k=cachekey(r);auto it=cachemap.find(k);if(it!=cachemap.end()){cacheused-=it->second.size;cachemap.erase(it);}while(cacheused+u.response.body.size()>c.cache&&!cacheorder.empty()){string old=cacheorder.front();cacheorder.pop_front();auto x=cachemap.find(old);if(x!=cachemap.end()){cacheused-=x->second.size;cachemap.erase(x);}}CacheEntry e{u.response,Clock::now()+chrono::milliseconds(ms),vary?"="+acceptenc(r):"",u.response.body.size()};cacheused+=e.size;cachemap[k]=move(e);cacheorder.push_back(k);}
struct Job{uint64_t id;Request r;shared_ptr<Config> c;};struct Done{uint64_t id;Response r;};static mutex qmu;static condition_variable qcv;static deque<Job> jobs;static deque<Done> dones;static int wakefd;static atomic<uint64_t> rr{0};static void worker(){for(;;){Job j;{unique_lock<mutex>l(qmu);qcv.wait(l,[]{return !jobs.empty();});j=move(jobs.front());jobs.pop_front();}Response out;if((j.r.method=="GET"||j.r.method=="HEAD")&&lookup(j.r,out)){}else{size_t n=j.c->ups.size(),idx=rr.fetch_add(1)%n;UpResult u=upstream(j.r,*j.c,idx);if(!u.ok&&(j.r.method=="GET"||j.r.method=="HEAD")&&n>1){bool firsttimeout=u.timeout;u=upstream(j.r,*j.c,(idx+1)%n);if(!u.ok)u.timeout=u.timeout||firsttimeout;}if(u.ok){out=u.response;storecache(j.r,*j.c,u);}else out=error(u.timeout?504:502);} {lock_guard<mutex>l(qmu);dones.push_back({j.id,move(out)});}uint64_t x=1;write(wakefd,&x,sizeof x);}}
struct Conn{int fd;uint64_t id;string in,out;size_t sent=0;uint64_t count=0;bool busy=false,closing=false;TP last=Clock::now(),headerstart{},wstart{};shared_ptr<Config> cfg;Request req;};
static string wire(Response &z,bool closeit,bool head){string h="HTTP/1.1 "+to_string(z.status)+" "+reason(z.status)+"\r\n"+z.headers+"Content-Length: "+to_string(z.length)+"\r\nConnection: "+(closeit?"close":"keep-alive")+"\r\n\r\n";if(!head)h+=z.body;return h;}
int main(int argc,char**argv){if(argc!=3||string(argv[1])!="--config")return 1;string configpath=argv[2];auto cfg=readconfig(configpath);if(!cfg)return 1;signal(SIGPIPE,SIG_IGN);signal(SIGHUP,onsig);signal(SIGTERM,onsig);int listener=socket(AF_INET,SOCK_STREAM|SOCK_NONBLOCK|SOCK_CLOEXEC,0);if(listener<0)return 1;int one=1;setsockopt(listener,SOL_SOCKET,SO_REUSEADDR,&one,sizeof one);if(bind(listener,(sockaddr*)&cfg->listenaddr,sizeof(sockaddr_in))||listen(listener,8192))return 1;int ep=epoll_create1(EPOLL_CLOEXEC);wakefd=eventfd(0,EFD_NONBLOCK|EFD_CLOEXEC);epoll_event ev{};ev.events=EPOLLIN;ev.data.u64=0;epoll_ctl(ep,EPOLL_CTL_ADD,listener,&ev);ev.data.u64=1;epoll_ctl(ep,EPOLL_CTL_ADD,wakefd,&ev);for(int i=0;i<16;i++)thread(worker).detach();unordered_map<uint64_t,unique_ptr<Conn>> conns;uint64_t nextid=2;bool draining=false;TP drainend;double tokens=cfg->burst;TP refill=Clock::now();auto mod=[&](Conn &c){epoll_event e{};e.data.u64=c.id;e.events=EPOLLRDHUP;if(!c.out.empty())e.events|=EPOLLOUT;else if(!c.busy)e.events|=EPOLLIN;epoll_ctl(ep,EPOLL_CTL_MOD,c.fd,&e);};auto del=[&](uint64_t id){auto it=conns.find(id);if(it==conns.end())return;epoll_ctl(ep,EPOLL_CTL_DEL,it->second->fd,nullptr);close(it->second->fd);conns.erase(it);};auto respond=[&](Conn&c,Response z,bool bad){c.count++;c.closing=bad||c.req.close||c.count>=c.cfg->maxreq||draining;c.out=wire(z,c.closing,c.req.head);c.sent=0;c.busy=false;c.wstart=Clock::now();mod(c);};auto process=[&](Conn&c){if(c.busy||!c.out.empty()||c.in.empty())return;auto now=Clock::now();if(c.headerstart==TP{})c.headerstart=now;size_t end=c.in.find("\r\n\r\n");if(end==string::npos){if(c.in.size()>cfg->hbytes){c.cfg=cfg;c.req=Request();respond(c,error(431),true);}else{for(size_t i=0;i<c.in.size();i++)if(c.in[i]=='\0'||(c.in[i]=='\n'&&(i==0||c.in[i-1]!='\r'))){c.cfg=cfg;c.req=Request();respond(c,error(400),true);break;}}return;}if(end+4>cfg->hbytes){c.cfg=cfg;c.req=Request();respond(c,error(431),true);return;}Request r;int e=parseheader(c.in.substr(0,end+4),*cfg,r);c.cfg=cfg;if(e){c.req=r;respond(c,error(e),true);return;}size_t consumed=0;string body;int b=reqbody(r,*cfg,c.in,end+4,body,consumed);if(b==0)return;if(b<0){c.req=r;respond(c,error(b==-2?413:400),true);return;}r.body=move(body);c.in.erase(0,consumed);c.headerstart=c.in.empty()?TP{}:now;c.req=move(r);if(cfg->rate){double elapsed=chrono::duration<double>(now-refill).count();tokens=min<double>(cfg->burst,tokens+elapsed*cfg->rate);refill=now;if(tokens<1){auto z=error(429);z.headers="Retry-After: "+to_string(max(1,(int)ceil((1-tokens)/cfg->rate)))+"\r\n";respond(c,z,false);return;}tokens-=1;}if(c.req.proxy){if(c.req.method!="GET"&&c.req.method!="HEAD"&&c.req.method!="POST"){respond(c,error(405),false);return;}Response z;if((c.req.method=="GET"||c.req.method=="HEAD")&&lookup(c.req,z)){respond(c,move(z),false);return;}c.busy=true;{lock_guard<mutex>l(qmu);jobs.push_back({c.id,c.req,c.cfg});}qcv.notify_one();mod(c);}else respond(c,local(c.req,*cfg),false);};epoll_event events[512];while(true){int flags=sigflag.exchange(0);if(flags&1){auto n=readconfig(configpath);if(n&&n->listen==cfg->listen){cfg=n;flushcache();tokens=cfg->burst;refill=Clock::now();}}if((flags&2)&&!draining){draining=true;drainend=Clock::now()+chrono::milliseconds(cfg->drain);epoll_ctl(ep,EPOLL_CTL_DEL,listener,nullptr);close(listener);vector<uint64_t> ids;for(auto &p:conns)if(!p.second->busy&&p.second->out.empty())ids.push_back(p.first);for(auto id:ids)del(id);}if(draining&&(conns.empty()||Clock::now()>=drainend))break;int n=epoll_wait(ep,events,512,50);if(n<0){if(errno==EINTR)continue;break;}for(int i=0;i<n;i++){auto id=events[i].data.u64;if(id==0){while(!draining){int fd=accept4(listener,nullptr,nullptr,SOCK_NONBLOCK|SOCK_CLOEXEC);if(fd<0){if(errno==EINTR)continue;break;}if(conns.size()>=cfg->maxconn){close(fd);continue;}auto c=make_unique<Conn>();c->fd=fd;c->id=nextid++;c->cfg=cfg;epoll_event e{};e.data.u64=c->id;e.events=EPOLLIN|EPOLLRDHUP;epoll_ctl(ep,EPOLL_CTL_ADD,fd,&e);conns[c->id]=move(c);}continue;}if(id==1){uint64_t v;while(read(wakefd,&v,sizeof v)>0){}deque<Done> ds;{lock_guard<mutex>l(qmu);ds.swap(dones);}for(auto &d:ds){auto it=conns.find(d.id);if(it!=conns.end()&&it->second->busy)respond(*it->second,move(d.r),false);}continue;}auto it=conns.find(id);if(it==conns.end())continue;Conn&c=*it->second;uint32_t flags=events[i].events;if(flags&EPOLLERR){del(id);continue;}if((flags&EPOLLIN)&&!c.busy&&c.out.empty()){char buf[8192];ssize_t k=recv(c.fd,buf,sizeof buf,0);if(k>0){if(c.in.empty())c.headerstart=Clock::now();c.in.append(buf,k);c.last=Clock::now();process(c);}else if(k==0){del(id);continue;}else if(errno!=EAGAIN&&errno!=EWOULDBLOCK&&errno!=EINTR){del(id);continue;}}it=conns.find(id);if(it==conns.end())continue;Conn &cc=*it->second;if((flags&EPOLLOUT)&&!cc.out.empty()){ssize_t k=send(cc.fd,cc.out.data()+cc.sent,cc.out.size()-cc.sent,MSG_NOSIGNAL);if(k>0){cc.sent+=k;cc.last=Clock::now();if(cc.sent==cc.out.size()){cc.out.clear();cc.sent=0;if(cc.closing){del(id);continue;}if(!cc.in.empty())process(cc);mod(cc);}}else if(k<0&&errno!=EAGAIN&&errno!=EWOULDBLOCK&&errno!=EINTR){del(id);continue;}}if((flags&EPOLLRDHUP)&&cc.out.empty()&&!cc.busy){del(id);continue;}}auto now=Clock::now();vector<uint64_t> expired;for(auto &p:conns){Conn &c=*p.second;if(!c.out.empty()){if(now-c.wstart>chrono::milliseconds(c.cfg->write))expired.push_back(p.first);}else if(!c.busy){if(c.headerstart!=TP{}&&now-c.headerstart>chrono::milliseconds(cfg->htime))expired.push_back(p.first);else if(c.headerstart==TP{}&&now-c.last>chrono::milliseconds(cfg->idle))expired.push_back(p.first);}}for(auto id:expired)del(id);}return 0;}
